# ---- Mission manager: loading, runner, directives and monitors, ending and results ---------------------------------
Mission.MHHHFOBJBAP = DefendTargetsMonitor                      # MissionManager.DefendTargetsMonitor's type; BeginDirective/MonitorDamageable/DefendFailed, fails when a watched body dies
Mission.AKKOFNMLBJC = DestroyTargetsMonitor                     # MissionManager.DestroyTargetsMonitor's type; DestroyedSucceeded/DestroyedFailed, completes when all watched are destroyed
Mission.KKIAFEBONCN = ScanTargetsMonitor                        # MissionManager.ScanTargetsMonitor's type; MonitorTargetable(target, ShipSystem), ScanSucceeded
Mission.KKIAFEBONCN/MHNHBMMOKIN = ScanTarget                    # { Targetable, Subsystem } entry of the scan monitor
Mission.MMENPGLIIPI = DirectiveMarkerMonitor                    # MissionManager.DirectiveMarkerMonitor's type; UpdateMarkers(DirectiveSectorIDs, MarkedSystemIDs), TrackEnemy, ImpulseStart/End
Mission.MMENPGLIIPI/JAEHNFAMLCE = DirectiveMarker               # Body, POI, Family, System, Directive, HasDirective, HasEnemy: one nav-map marker
Mission.MMENPGLIIPI/IHDPLGLBKEO = ImpulseMarker                 # Ship, Marker, OriginPOI, DestPOI: a marker riding a ship at impulse
Mission.MissionManager/CFBAPFAOKJL = MissionFailureType         # DestroyShip, Catastrophe: SendMissionFailureEvent's argument
Mission.MissionManager/IJAAEFAKEKD = DestinationType            # Warp, Impulse, Local: SendNewDestinationEvent's argument
Mission.MissionManager/NFHNOHEGADD = SyncFlags                  # WarpingEnabled, CannotExitWarp, MissionSuccess, PauseLoadingNewSystem, UseAltWarpDests: the byte NetworkSerialize writes
BNDCOCHFOCN/OFENODEIEIN = HealthThreshold                       # HealthPercent, VOEvent, BridgeObject, Delay
COHHFPKDHMB = ShipComputerAlert                                 # Hull50, Hull25, EnginesCritical...: ShipComputerVOManager.GetEventName/GetVOObject keys
KLBDPGLGIPM = Telemetry                                         # static Send*Event (MissionContextStart, MissionCompleted, Warp, Scan...): analytics
KLBDPGLGIPM/IENEBPHBFBG = TelemetryContextType                  # bridge, mission, proceduralData, solarSystem
KLBDPGLGIPM/HMPCHLAAIEK = ProceduralMissionContext              # new'd in MissionManager.CreateProceduralRunner(proceduralData, objective table name, objective script)
KLBDPGLGIPM/NLHKIDLOCJE = CampaignMissionContext                # new'd in MissionManager.CreateRunner(mission, sequence type name)
Tables.PMOFEENLBEK = IWeightedTable                             # WeightedEntries: MissionTable / ObjectiveTable, picked by MissionManager.PickWeighted
Tables.CKBAPONIMKM = IWeightedEntry                             # Weight: MissionTableEntry / ObjectiveTableEntry
Sector.FEBFIKOLFHC = ISpawnManager                              # ScenarioBase.Init's 2nd argument (SectorMap.SpawnManager, a SectorSpawnManager); SpawnResource(SpawnRequest)
BHNEPPPPMKH/EIKCLNAPKBE = SpawnPointChoice                      # Default, UseAlternatives: StartSystemSelection.SpawnChoice; FindSpawnPoint picks Player vs AltPlayerSpawn tags
BHNEPPPPMKH/FDNFBLDLILH = WarpChoice                            # DefaultOnly, IncludeAlts: StartSystemSelection.WarpChoice -> MissionManager.UseAltWarpDestinations
UI.CAJKAPALCCO/GCIOEGLLOLP = Severity                           # Warning, Catastrophe: MissionManager.DisplayViewScreenMessage's first argument
MissionResultManager/EGHFCBPKDLF = DisplayedStats               # flags PlayTime, HullIntegrity, TorpedoesFired, EnemiesDestroyed...: SetStatsToDisplay / ShouldDisplayStat
MissionResultManager/LNNFFMBBFGO = MissionResult                # MissionResultString, WasSuccess: AddMissionResult's line on the results screen
MissionResultManager/LICFMBEEMCL = MissionStat                  # DisplayName, Value: a stat row on the results screen
Mission.BEEEGBFNGFJ = EndMissionRequestEvent                    # field MissionStatus; PauseMenuUI (aborted), GamePhase_Bridge (captainLeft/failure) send it; MissionManager -> EndMission
Mission.KCJJDIDAPGO = FadeToBridgeEvent                         # GamePhase_Bridge.FadeToBridge once every player synced "FadeToBridge"; MissionManager starts SetSafeToRunSequence, MissionResultManager resets
Mission.HFEDFBPLFDO = DirectiveAddedEvent                       # sent by MissionManager.AddDirective / AddSubDirective; ConsoleCaptain flashes Objectives
Mission.MDANIENEFJG = DirectiveCompletedEvent                   # sent by MissionManager.CompleteDirective; ConsoleCaptain.OnDirectiveCompleted plays a sound
Mission.PDDPJHHHAHH = DirectiveRemovedEvent                     # confirms names.map guess DirectiveRemovedEvent?: RemoveDirective and each monitor's Reset send it with the description
Mission.BPNNPMLKJFK = DirectiveMarkerChangedEvent               # confirms names.map guess: DirectiveMarkerMonitor sends it on every marker add/remove/HasDirective/HasEnemy change
Mission.ADGAMLPFAPB = ImpulseMarkerEvent                        # Marker (ImpulseMarker), Start: DirectiveMarkerMonitor, when a marked ship starts/stops impulse
Mission.ANACDILHCBL = MarkedSystemsChangedEvent                 # Monitor: DirectiveMarkerMonitor.UpdateMarkers when MarkedSystemIDs changed
Sector.LIIFMAGDNBD = ImpulseTravelEvent                         # Ship, Origin, Destination, Start: AgentShip sends; MissionManager -> DirectiveMarkerMonitor.ImpulseStart/End
PNMACMPDBKB = SystemLoadedEvent                                 # SectorMap.LoadStartingSystem / ChangeActiveSystem send it; MissionManager rebuilds POIAvailable
HHKNBGIFCMN = NewWarpDestinationEvent                           # Multicast_SendNewDestinationEvent(Warp); ConsoleHelm listens
HMHGNODAHBG = NewImpulseDestinationEvent                        # Multicast_SendNewDestinationEvent(Impulse); ConsoleHelm listens
GENJJEPLDDM = NewLocalDestinationEvent                          # Multicast_SendNewDestinationEvent(Local); ConsoleHelm listens
IHDFPIOIODH = CatastropheEvent                                  # Multicast_SendMissionFailureEvent(Catastrophe)
