ScenarioBase::PJGOCMBMFGE = SharedUpdate                        # Update(): every client; MissionManager: monitors' Update, UpdateMarkers
ScenarioBase::IAANKKNJCJM = OnBodySpawned                       # OnBodySpawnedEvent -> (body)
ScenarioBase::CNJHKDOGNAP = _spawnManager                       # Init(sector, spawnManager); MissionManager.SpawnManager returns it
ScenarioBase::LFBBCGCLOKG = _sector                             # Init's ISector; MissionManager.Sector returns it  # replaces auto: _iSector?
Mission.MissionManager::KEPMGGGIOFF = OwnerStart                # override of ScenarioBase.OwnerStart: PauseLoadingNewSystem=false; SpawnPlayerShip()
Mission.MissionManager::AOMDODPFEIB = SharedStart               # override: DirectiveMarkerMonitor = new(sector)
Mission.MissionManager::PJGOCMBMFGE = SharedUpdate              # override: while safe and running, Defend/Destroy/Scan monitors Update, UpdateMarkers
