Mission.MissionManager::AMMPAAFBICE = OnRunnerSuccess           # Runner.OnMissionSuccess -> EndMission(success, line1, line2)
Mission.MissionManager::GIGECLHKCOI = OnRunnerFailure           # Runner.OnMissionFailure -> EndMission(failure, line1, line2)
